    private function readTemplateSnippet(ServerRequestInterface $request): TemplateSnippetUpdateParams
    {
        $this->logDebug("Read entity for Template snippet");
        $span = $this->startSpan("Read entity for Template snippet");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new TemplateSnippetUpdateParams();
            $valueUid = TemplateSnippetUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            $valueCode = TemplateSnippetCodeVO::tryFrom($body['code'] ?? null, $errorsList);
            if (null !== $valueCode) {
                $value->code($valueCode);
            }
            if (in_array('tenant', array_keys($body))) {
                $valueTenant = TemplateSnippetTenantVO::tryFrom(isset($body['tenant']['$ref']) ? new TenantRef($body['tenant']['$ref']) : null, $errorsList);
                if (null !== $valueTenant) {
                    $value->tenant($valueTenant);
                }
            }
            $valueContentHtml = TemplateSnippetContentHtmlVO::tryFrom($body['contentHtml'] ?? null, $errorsList);
            if (null !== $valueContentHtml) {
                $value->contentHtml($valueContentHtml);
            }
            $value->version(TemplateSnippetVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
