    private function mapTemplateSnippet(ServerRequestInterface $request, TemplateSnippetUpdateResult $value): TemplateSnippetApiDTO
    {
        $this->logDebug("Map entity to output dto for Template snippet");
        $span = $this->startSpan("Map entity to output dto for Template snippet");
        try {
            $tenant = $value->getTenant();
            $dto = new TemplateSnippetApiDTO();
            $dto->uid = $value->getUid();
            $dto->code = $value->getCode();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->contentHtml = $value->getContentHtml();
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
